using System;using System.IO;using System.Reflection;using System.Runtime.CompilerServices;using VRageMath;using SEMC.V2;
class CheckAlign{
static string root=@"C:\Users\konra\Documents\SEMC-Lab";
static void Main(){AppDomain.CurrentDomain.AssemblyResolve+=(o,e)=>{string n=new AssemblyName(e.Name).Name+".dll";foreach(string d in new[]{Path.Combine(root,"research-se"),@"C:\Program Files (x86)\Steam\steamapps\common\SpaceEngineers\Bin64",Path.Combine(root,@"tools\Pulsar\Libraries\Legacy")}){string p=Path.Combine(d,n);if(File.Exists(p))return Assembly.LoadFrom(p);}return null;};Run();}
[MethodImpl(MethodImplOptions.NoInlining)] static void Run(){MatrixD old=MatrixD.CreateFromYawPitchRoll(.31f,.42f,.07f);old.Translation=new Vector3D(19800,11000,56000);MatrixD next=MatrixD.CreateFromYawPitchRoll(-.22f,.14f,.83f);next.Translation=new Vector3D(19840,11010,56020);MatrixD[] saved=new MatrixD[5];saved[0]=old;for(int i=1;i<5;i++){MatrixD rel=MatrixD.CreateRotationX(i*.2);rel.Translation=new Vector3D((i%2==0?-1:1)*1.6,-.9,i<=2?-2:2);saved[i]=rel*old;}var method=typeof(RuntimeControl).GetMethod("AlignedGroupPoses",BindingFlags.NonPublic|BindingFlags.Static);MatrixD[] result=(MatrixD[])method.Invoke(null,new object[]{saved,old,next});MatrixD ni=MatrixD.Invert(next),oi=MatrixD.Invert(old);for(int i=0;i<5;i++){MatrixD before=saved[i]*oi,after=result[i]*ni;if(Vector3D.Distance(before.Translation,after.Translation)>1e-7||Vector3D.Distance(before.Forward,after.Forward)>1e-7||Vector3D.Distance(before.Up,after.Up)>1e-7)throw new Exception("relative pose changed");}if(Vector3D.Distance(result[0].Translation,next.Translation)>1e-7||Vector3D.Distance(result[0].Forward,next.Forward)>1e-7||Vector3D.Distance(result[0].Up,next.Up)>1e-7)throw new Exception("main pose mismatch");Console.WriteLine("PASS five saved poses: main exactly aligned, all four wheel positions/orientations relative to main preserved; no live entity calls.");}}